<?php /** Home: the Billing region (slice 6). Data: b (billing_summary), tz */
$money = static fn (array $byCur): string => $byCur === [] ? '—' : implode(' + ', array_map(static fn (string $c, string $a): string => fmt_money($a, $c), array_keys($byCur), array_values($byCur)));
$bucket = ['current_due' => 'Current', 'd1_30' => '1–30', 'd31_60' => '31–60', 'd61_90' => '61–90', 'd90_plus' => '90+']; ?>
<div class="card mb-3" id="home-billing"><div class="card-header"><h5 class="card-title mb-0">Billing</h5></div>
    <div class="list-group list-group-flush">
        <a href="/billing/unbilled" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center" id="home-billing-unbilled" hx-get="/billing/unbilled" hx-target="#page-content" hx-push-url="/billing/unbilled"><span><i class="feather-layers me-2"></i>Unbilled work</span><strong id="home-billing-unbilled-amount"><?= e($money($b['wip'])) ?></strong></a>
        <a href="/invoices/?status=draft" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center" id="home-billing-drafts" hx-get="/invoices/?status=draft" hx-target="#page-content" hx-push-url="/invoices/?status=draft"><span><i class="feather-file-text me-2"></i>Drafts to issue</span><strong id="home-billing-drafts-count"><?= (int) $b['draft_count'] ?></strong></a>
        <a href="/billing/due" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center" id="home-billing-due" hx-get="/billing/due" hx-target="#page-content" hx-push-url="/billing/due"><span><i class="feather-calendar me-2"></i>Due to draft</span><strong id="home-billing-due-count"><?= (int) $b['due_to_draft'] ?></strong></a>
        <a href="/invoices/?status=open" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center" id="home-billing-owed" hx-get="/invoices/?status=open" hx-target="#page-content" hx-push-url="/invoices/?status=open"><span><i class="feather-clock me-2"></i>Who owes us<?= (int) $b['overdue'] > 0 ? ' <span class="badge bg-soft-danger text-danger">' . (int) $b['overdue'] . ' overdue</span>' : '' ?></span><strong id="home-billing-owed-amount"><?= e($money($b['owed'])) ?></strong></a>
        <?php if (has_right('billing.write')): ?><a href="/billing/claims" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center" id="home-billing-claims" hx-get="/billing/claims" hx-target="#page-content" hx-push-url="/billing/claims"><span><i class="feather-inbox me-2"></i>Payment claims waiting</span><strong id="home-billing-claims-count"><?= (int) $b['claims'] ?></strong></a><?php endif; ?>
    </div>
    <?php if (!empty($b['statement'])): $st = $b['statement']; ?><div class="list-group list-group-flush border-top"><a href="/usage/os" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center" id="home-billing-statement" hx-get="/usage/os" hx-target="#page-content" hx-push-url="/usage/os"><span><i class="feather-cpu me-2"></i>OS statement <?= e($st['period']) ?> <span class="text-muted">(<?= e($st['status']) ?>)</span></span><strong id="home-billing-statement-remainder"><?= (float) $st['remainder'] > 0 ? e(number_format((float) $st['remainder'], 2)) . ' to allocate' : 'allocated' ?></strong></a></div><?php endif; ?>
    <?php if (array_filter($b['aging'])): ?><div class="card-body p-3 border-top"><div class="row g-2 text-center" id="home-billing-aging"><?php foreach ($bucket as $k => $l): ?><div class="col"><div class="fs-12 text-muted"><?= e($l) ?></div><div class="fw-semibold fs-12" id="home-billing-aging-<?= e($k) ?>"><?= e($money($b['aging'][$k])) ?></div></div><?php endforeach; ?></div></div><?php endif; ?>
    <?php if ($b['drafts'] !== []): ?><div class="list-group list-group-flush border-top" id="home-billing-draft-list"><?php foreach ($b['drafts'] as $d): ?><div class="list-group-item fs-12 d-flex justify-content-between" id="home-draft-<?= (int) $d['invoice_id'] ?>"><?= hx_link('/invoices/' . (int) $d['invoice_id'], 'Draft for ' . e($d['engagement_number'])) ?><span><?= e(fmt_money($d['total'], $d['currency'])) ?></span></div><?php endforeach; ?></div><?php endif; ?>
</div>
